<template>
  <d2-container>
    <div>
      <div v-if="nowView === 1">
        <vxe-form :data="formData" @submit="findList">
          <vxe-form-item span="24">
            <template #default>
              <vxe-button type="submit" status="primary">查询</vxe-button>
              <vxe-button type="reset">重置</vxe-button>
            </template>
          </vxe-form-item>
          <vxe-form-item
            title="订单日期"
            field="date"
            span="8"
            :item-render="{}"
            title-overflow="ellipsis"
          >
            <!-- <template #default="params">
                  <vxe-input v-model="params.data.date" type="date" placeholder="请选择日期" clearable @change="$refs.xForm.updateStatus(params)"></vxe-input>
                </template> -->
            <template #default="{ data }">
              <vxe-input
                v-model="data.date"
                type="date"
                placeholder="请选择日期"
                clearable
              ></vxe-input>
            </template>
          </vxe-form-item>
          <vxe-form-item
            title="客户名称"
            field="khmc"
            span="8"
            :item-render="{}"
            class="ss"
          >
            <template #default="{ data }">
              <vxe-select v-model="data.khmc" placeholder="请选择性别">
                <vxe-option
                  v-for="(item, index) in khList"
                  :key="index"
                  :value="item.value"
                  :label="item.label"
                ></vxe-option>
              </vxe-select>
            </template>
          </vxe-form-item>
          <vxe-form-item
            title="业务员"
            field="name"
            span="8"
            :item-render="{}"
            class="ss"
          >
            <template #default="{ data }">
              <vxe-select v-model="data.name" placeholder="请选择性别">
                <vxe-option
                  v-for="(item, index) in nameList"
                  :key="index"
                  :value="item.value"
                  :label="item.label"
                ></vxe-option>
              </vxe-select>
            </template>
          </vxe-form-item>
          <vxe-form-item
            title="订单编号"
            field="ddbh"
            span="8"
            :item-render="{}"
            class="ss"
          >
            <template #default="{ data }">
              <vxe-input
                v-model="data.ddbh"
                placeholder="请输入名称"
              ></vxe-input>
            </template>
          </vxe-form-item>
          <vxe-form-item
            title="付款方式"
            field="fkfs"
            span="8"
            :item-render="{}"
            class="ss"
          >
            <template #default="{ data }">
              <vxe-select v-model="data.fkfs" placeholder="请选择性别">
                <vxe-option
                  v-for="(item, index) in fkfsList"
                  :key="index"
                  :value="item.value"
                  :label="item.label"
                ></vxe-option>
              </vxe-select>
            </template>
          </vxe-form-item>
          <vxe-form-item
            title="总金额"
            field="zje"
            span="8"
            :item-render="{}"
            class="ss"
          >
            <template #default="{ data }">
              <vxe-input
                v-model="data.zje"
                placeholder="请输入名称"
              ></vxe-input>
            </template>
          </vxe-form-item>
        </vxe-form>

        <vxe-table
          border
          resizable
          show-overflow
          :loading="loading"
          :data="tableData"
          :edit-config="{ trigger: 'click', mode: 'cell' }"
        >
          <vxe-column type="seq" width="60"></vxe-column>
          <vxe-column
            field="产品ID"
            title="产品ID"
            :edit-render="{ name: 'input', attrs: { type: 'text' } }"
          ></vxe-column>
          <vxe-column
            field="产品名称"
            title="产品名称"
            :edit-render="{ name: '$select', options: cpList }"
          ></vxe-column>
          <vxe-column
            field="单价"
            title="单价"
            :edit-render="{ name: 'input', attrs: { type: 'text' } }"
          ></vxe-column>
          <vxe-column
            field="数量"
            title="数量"
            :edit-render="{ name: '$input', props: { type: 'number' } }"
          ></vxe-column>
          <vxe-column field="金额" title="金额">
            <template #default="{ row }">
              <span>{{ row.金额 }} </span>
              <vxe-input type="text">{{ row.单价 * row.数量 }}</vxe-input>
            </template>
          </vxe-column>
        </vxe-table>
      </div>
    </div>
  </d2-container>
</template>

<script>
export default {
  name: "CaiInfo",
  data() {
    return {
      loading: false,
      formData: {
        name: "",
        sex: "",
        date: "",
        ddbh: "",
        fkfs: "",
        khmc: "",
        zje: "",
      },
      fkfsList: [],
      nameList: [],
      khList: [],
      cpList: [],
      tableData: [],
      nowView: 1,
    };
  },
};
</script>


<style>
.my-grid66 .alert-message {
  height: 40px;
  display: flex;
  align-items: center;
  margin: 10px 0;
  border-radius: 4px;
  background-color: #e6f7ff;
  border: 1px solid #91d5ff;
}
.my-grid66 .alert-message-icon {
  width: 30px;
  text-align: center;
  color: #409eff;
  margin-right: 8px;
}
.my-grid66 .alert-message-content {
  flex-grow: 1;
  padding-right: 20px;
}
.my-grid66 .page-left {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
}
.my-grid66 .select-count {
  display: inline-block;
  vertical-align: middle;
}
.my-grid66 .my-input {
  width: 100%;
}
.my-grid66 .first-col {
  position: relative;
  height: 20px;
}
.my-grid66 .first-col:before {
  content: "";
  position: absolute;
  left: -14px;
  top: 10px;
  width: 204px;
  height: 1px;
  transform: rotate(13deg);
  background-color: #e8eaec;
}
.my-grid66 .first-col .first-col-top {
  position: absolute;
  right: 4px;
  top: -10px;
}
.my-grid66 .first-col .first-col-bottom {
  position: absolute;
  left: 4px;
  bottom: -10px;
}

.el-col {
  border-radius: 4px;
}
.bg-purple-dark {
  background: #99a9bf;
}
.bg-purple {
  background: #d3dce6;
}
.bg-purple-light {
  background: #e5e9f2;
}
.grid-content {
  border-radius: 4px;
  min-height: 36px;
}
.ss {
  margin-left: 5px;
}
</style>
<vue-filename-injector>
export default function (Component) {
  Component.options.__source = "src/views/pages/CaiInfo/caigou.vue"
}
